head.script:
scwin.trigger1_onclick = function(e) {
    dataList1.setJSON(jsonData1); //jsonData1 을 dataList1 에 표현  
};
scwin.trigger2_onclick = function(e) {
    dataList1.insertRow(); // dataList1 에 Row 추가
};
scwin.trigger3_onclick = function(e) {
    dataList1.removeRow(3); // dataList1 에 3번째 Row부터 삭제
    //			dataList1.deleteRow( 3 );	// dataList1 에 3번째 Row부터 삭제 (삭제상테 확인)
};
scwin.trigger4_onclick = function(e) {
    dataList1.removeColumnFilterAll(); //dataList1 의 컬럼과 필터를 모두 삭제
    var jsonData2 = [ //변수명은 jsonData2 선언           
        {
            "col1": "가",
            "col2": "B",
            "col3": 3,
            "rowStatus": "R"
        },
        {
            "col1": "가",
            "col2": "A",
            "col3": 2,
            "rowStatus": "R"
        },
        {
            "col1": "가",
            "col2": "A",
            "col3": 1,
            "rowStatus": "R"
        }
    ];
    dataList1.setJSON(jsonData2); //jsonData2 를 dataList1 에 표현
};
scwin.trigger5_onclick = function(e) {
    dataList1.setCellData(1, 2, "꺄오");
};
scwin.trigger6_onclick = function(e) {
    var options = {}; //변수명은 options 선언
    options.fileName = "excel.xls"; //다운로드할 파일명과 확장자 지정
    options.type = "1"; //0 인 경우 실제데이터 / 1 인 경우 눈에 보이는 데이터 다운로드
    options.useStyle = "true"; //지정한 bodyColor 적용
    options.spanAll = "true"; //엑셀 다운로드시 drilldown gridView의 전체목록을 펼쳐서 출력
    gridView1.advancedExcelDownload(options); //gridView1 에 표현된 데이터를 엑셀다운로드
};
scwin.trigger7_onclick = function(e) {
    var options = {}; //변수명은 options 선언
    options.fileName = "excel.xlsx"; //다운로드할 파일명과 확장자 지정
    options.type = "1"; //0 인 경우 실제데이터 / 1 인 경우 눈에 보이는 데이터 다운로드
    options.useStyle = "true"; //지정한 bodyColor 적용
    options.spanAll = "true"; //엑셀 다운로드시 drilldown gridView의 전체목록을 펼쳐서 출력
    gridView1.advancedExcelDownload(options); //gridView1 에 표현된 데이터를 엑셀다운로드
};
scwin.trigger8_onclick = function(e) {
    var options = {}; //변수명은 options 선언
    options.type = "1"; //0 인 경우 실제데이터, 즉 Value.xls 만 업로드 / 1 인 경우 눈에 보이는 데이터, 즉 label.xls 만 업로드
    //				options.headerExist = "1";	//헤더의 존재유무
    options.startRowIndex = "1"; //데이터가 시작되는 row 의 index (헤더 포함)
    //				options.Columnindex = "0";	//데이터가 시작되는 column 의 index (헤더포함)
    //				options.sheetNo = 0;	//excel 의 sheet 번호
    //				options.pwd = "1234";	//excel 의 비밀번호
    gridView1.advancedExcelUpload(options); //업로드된 엑셀 데이터를 gridView1 에 표현
};
scwin.__hasError = function() {
    var logs = WebSquare.logger.getLog();
    var hasErrorIdCol1 = logs.indexOf("id[col1]") > 0;
    var hasErrorIdCol7 = logs.indexOf("id[column7]") > 0;
    return hasErrorIdCol7 && hasErrorIdCol1;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. 브라우저에서 로그 (Ctrl + 마우스 오른쪽) 를 실행한다.
    //2. Run the log in the browser (Ctrl + right mouse).
    // verify step 2. 로그에 에러로그가 표시된다. (그림2 참고)
    //2. An error log is displayed in the log. (See Figure 2)
    WebSquare.wUnit.addCommand("assert", "scwin.__hasError()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
